"""Build the fixed eight-chapter WWII scope from cited factual annotations.
No invented occupation/front polygons: national-status snapshots, located events,
cleared Army atlas cartography and a declared schematic milestone movement.
Run python tools/build/ww2_history.py; atlas scans: ww2_history_maps.py.
"""
from pathlib import Path
import json
from ww2_border_names import build as build_border_names
build_border_names()
R=Path(__file__).resolve().parents[2];D=R/'data/history/ww2';D.mkdir(parents=True,exist_ok=True)
A='https://www.archives.gov/';U='https://encyclopedia.ushmm.org/content/en/article/';H='https://history.state.gov/';N='https://www.history.navy.mil/'
DK='https://en.natmus.dk/historical-knowledge/denmark/german-occupation-1940-1945/'
DK_END='https://natmus.dk/historisk-viden/danmark/besaettelsestiden-1940-1945/besaettelsen-kort-fortalt/befrielsen/'
NO_END='https://www.regjeringen.no/en/the-government/previous-governments/regjeringer-siden-1814/historiske-regjeringer/norways-governments-1940-1945/the-chief-officers-in-oslo-may-1945/id438698/'
ARMY='https://history.army.mil/Research/Reference-Topics/Army-Campaigns/Brief-Summaries/World-War-II/World-War-II-European-African-Middle-Eastern-Theater/'
RHINE='https://www.first.army.mil/History/This-Day-in-First-Army-History/March/'
ATLAS='https://maps.lib.utexas.edu/maps/historical/history_ww2.html'
POTSDAM=H+'historicaldocuments/frus1945Berlinv02/d1152'
E={'mode':'globe','center':[16,51],'zoom':4}
COMMON='Original Orbis factual annotations checked 14 October 2026; event-card links and scene-indexed notes identify the evidence. Points locate selected places approximately, not military fronts, camp boundaries or casualty-density surfaces. Contemporary coastlines are reference geography; modern country borders are hidden unless a scene explicitly compares country status. No comprehensive monthly occupation map is claimed.'
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def chapter(id,title,hook,rows,extra=None):
 items=[];scenes=[]
 for i,(heading,text,label,at,date,url,view) in enumerate(rows):
  items.append({'title':label,'text':text,'date':date,'at':at,'kind':str(i),'source':'Primary record / specialist museum account','url':url})
  scenes.append({'title':heading,'text':text,'view':view or E,'modernBorders':False,'layers':[{'type':'cards','data':'events','year':date,'kinds':[str(i)],'list':True}], 'sources':['editorial']})
 ds={'source':'editorial','asOf':'Historical observation dates stated per event','retrieved':'2026-10-14','note':COMMON,'kinds':{str(i):{'label':row[2],'color':('muted' if id=='ww2-holocaust' else ['c1','c2','c3','c4','c5'][i%5])} for i,row in enumerate(rows)},'items':items}
 st={'id':id,'cat':'Geopolitics','title':title,'hook':hook,'updated':'2026-10-14','notes':COMMON+' Sources by scene: '+'; '.join(f'{i+1}. {row[0]}: {row[5]}' for i,row in enumerate(rows)), 'data':{'events':f'data/history/ww2/{id}.json'},'sources':['editorial','naturalearth'],'scenes':scenes}
 if id=='ww2-bombing':st['notes']+=' Nagasaki terrain and damage context: Manhattan Engineer District, The Atomic Bombings of Hiroshima and Nagasaki (1946), chapter 9, https://www.atomicarchive.com/resources/documents/med/med_chp9.html (primary report transcription; no numerical damage claims imported).'
 if extra:extra(st,ds)
 write(D/(id+'.json'),ds);write(R/'stories'/(id+'.json'),st)
def before(st,d):
 st['data']['borders']='data/history/ww2/borders-names.json';st['sources'].append('cshapes')
 st['scenes'][0]['layers']=[{'type':'borders','data':'borders','year':1938,'labels':False}]
 st['scenes'][0]['points']=[{'at':[13.4,52.5],'label':'Germany','color':'muted','r':3},{'at':[14.5,47.5],'label':'Austria','color':'muted','r':3},{'at':[18,49.5],'label':'Czechoslovakia','color':'muted','r':3}]
 st['notes']+=' CShapes 2.0 snapshot date 1 January 1938, before Anschluss and Munich. CC BY-NC-SA 4.0; it encodes diplomatic state/dependency boundaries and omits small changes. Later event scenes do not redraw those borders.'
chapter('ww2-before','Europe before the war','A diplomatic map and the decisions that unravelled it.',[
 ('A snapshot before the annexations','CShapes records state boundaries on 1 January 1938. Austria and Czechoslovakia still appear separately. This is diplomatic geography before the year’s annexations, not a map of the eve of war in September 1939.','Europe: January1938',[16,51],1938,'https://icr.ethz.ch/data/cshapes/',None),
 ('Austria is annexed','German troops entered Austria on 12 March 1938; the Anschluss law incorporated it into Nazi Germany the following day. Vienna locates the annexation. No new territorial polygon is inferred from this point.','Vienna',[16.37,48.21],19380313,U+'nazi-territorial-aggression-the-anschluss',{'mode':'globe','center':[16,48],'zoom':5}),
 ('Munich changes Czechoslovakia’s position','The agreement reached at Munich on 29–30 September 1938 allowed German annexation of the Sudetenland. The city point locates the negotiations; it does not draw the affected border districts.','Munich',[11.58,48.14],19380930,'https://encyclopedia.ushmm.org/content/en/timeline-event/holocaust/1933-1938/munich-agreement',None),
 ('A pact made in Moscow','Germany and the Soviet Union signed their non-aggression pact on 23 August 1939. Its secret protocol divided spheres in eastern Europe and provided for Poland’s partition. The Moscow point locates the agreement, not its territorial clauses.','Moscow',[37.62,55.75],19390823,U+'the-soviet-union-and-the-eastern-front',{'mode':'globe','center':[29,53],'zoom':3.2}),
],before)
def expansion(st,d):
 d['sets']={'nordic':{'label':'Selected national occupation status','byYear':{
  '19400409':{'DNK':'occupied','NOR':'fighting'},'19400610':{'DNK':'occupied','NOR':'occupied'},'19450505':{'DNK':'liberated','NOR':'occupied'},'19450508':{'DNK':'liberated','NOR':'liberated'}},
  'labels':{'occupied':'German occupation (national status)','fighting':'Invasion; fighting continues','liberated':'Main liberation/capitulation date'}}}
 d['occupationEvidence']=[{'country':'DNK','from':19400409,'to':19450505,'urls':[DK,DK_END],'precision':'National status; Bornholm exception not mapped as a control polygon.'},{'country':'NOR','from':19400610,'to':19450508,'urls':[U+'norway',NO_END],'precision':'Surrender/occupation at national scale, not every island or local troop position.'}]
 sc=st['scenes'][1];sc.update(modernBorders=True,countryLabels=True,timeline={'years':[19400409,19400610,19450505,19450508],'format':'date','start':19400610,'captions':{'19400409':'Denmark surrenders; Norway continues fighting','19400610':'Norway surrenders','19450505':'Denmark’s main liberation date; Bornholm exception','19450508':'German capitulation in Norway'}})
 sc['layers']=[{'type':'categories','data':'events','set':'nordic','year':'t','colors':{'occupied':'c2','fighting':'c3','liberated':'c4'}}]
 sc['points']=[{'at':[12.57,55.68],'label':'Copenhagen','color':'muted','r':3}]
 st['data']['atlas']='data/history/ww2/northern-europe-overlay.json';st['sources'].append('us-army-atlas')
 st['scenes'][3]['layers']=[{'type':'overlay','data':'atlas','opacity':0.88,'title':'Army atlas: June 1944–May 1945 (overview)'}]
 st['scenes'][3]['view']={'mode':'globe','center':[5,50.5],'zoom':8}
 path=[[-0.87,49.37,19440606],[2.35,48.86,19440825],[7.23,50.58,19450307]]
 d['moves']={'west':[{'name':'Allied milestones (schematic)','path':path,'color':'c1'}]}
 d['movementEvidence']=[{'at':path[0][:2],'date':path[0][2],'place':'Normandy beachhead area','url':ARMY},{'at':path[1][:2],'date':path[1][2],'place':'Paris','url':ARMY},{'at':path[2][:2],'date':path[2][2],'place':'Remagen bridge','url':RHINE}]
 st['scenes'][4]['timeline']={'years':[p[2] for p in path],'format':'date','start':19450307};st['scenes'][4]['layers']=[{'type':'moves','data':'events','set':'west','year':'t','labels':True}]
 st['notes']+=' Nordic snapshot dates: '+DK+'; '+DK_END+'; '+U+'norway; '+NO_END+'. Colours classify the countries at national scale on modern reference outlines, not every locality, island, troop position or front. Bornholm is an explicit exception to Denmark’s main liberation date. Western milestones: '+ARMY+'; '+RHINE+'. Waypoints are rounded locations of dated events; connectors and interpolated positions are schematic, not one unit’s march. Army scan: '+ATLAS+'; overview warp mean4.42px/max6.38px across11 city points; original arrows have different dates and do not describe one simultaneous front.'
chapter('ww2-expansion','Expansion and occupation','Invasion, national occupation and campaign maps describe different things.',[
 ('Poland is attacked from two sides','Germany invaded Poland on 1 September 1939; the Soviet Union invaded from the east on 17 September. The Warsaw point locates the country’s capital, without inventing a partition or a daily front.','Warsaw',[21.01,52.23],19390917,U+'invasion-of-poland-fall-1939',None),
 ('Two dated occupation cases','Denmark surrendered on 9 April 1940; Norway fought until 10 June. Follow national occupation status through Denmark’s main liberation date, 5 May 1945, and Norway’s capitulation, 8 May. Modern outlines are reference geography; Bornholm is an exception to Denmark’s main date.','Nordic occupation',[10,61],19400610,DK,{'mode':'globe','center':[12,60],'zoom':3.5}),
 ('France’s defeat did not create one uniform regime','Germany defeated France in June 1940. Occupied areas and the Vichy regime had different administrative arrangements. Paris locates the capital; this point does not fill all of France as one continuous occupied area.','Paris',[2.35,48.86],1940,U+'france',{'mode':'globe','center':[3,49],'zoom':4.5}),
 ('An atlas of the western advance','The US Army’s Northern Europe atlas combines arrows dated from June 1944 to May 1945. Its geography is warped approximately onto this map for overview reading. Use opacity to compare; the arrows are a campaign summary, not one dated front.','Western Europe',[5,50],1945,ATLAS,{'mode':'globe','center':[5,50.5],'zoom':5}),
 ('From the beachhead to the Rhine','Use the dated slider to follow selected Allied milestones: Normandy on 6 June 1944, Paris on 25 August and Remagen on 7 March 1945. The joining line is schematic; it does not identify a single army’s route.','Allied milestones',[2,49],1945,ARMY,{'mode':'globe','center':[3,50],'zoom':5}),
 ('Bornholm complicates a national liberation date','The Danish National Museum notes that Bornholm experienced Soviet bombardment during Denmark’s liberation. A country-level status colour cannot settle this island’s local control history. The point identifies the exception rather than drawing an unsupported control polygon.','Bornholm',[14.92,55.12],1945,DK_END,{'mode':'globe','center':[13,55.5],'zoom':5}),
],expansion)
chapter('ww2-east','The Eastern Front','The German–Soviet war moved through cities and devastated populations.',[
 ('The invasion of the Soviet Union','Nazi Germany and its allies attacked the Soviet Union on 22 June 1941. Minsk locates one part of the vast theatre; a point is not an invasion front. USHMM describes this as a war of annihilation against civilians as well as armies.','Minsk',[27.56,53.9],19410622,U+'the-soviet-union-and-the-eastern-front',{'mode':'globe','center':[31,53],'zoom':3.5}),
 ('Leningrad: a city under siege','German forces besieged Leningrad during the war. The siege subjected civilians to starvation and severe suffering. The city point locates the human geography of the siege; it does not delineate the encirclement.','Leningrad',[30.32,59.94],1941,'https://www.dhm.de/lemo/kapitel/der-zweite-weltkrieg/kriegsverlauf/belagerung-von-leningrad',{'mode':'globe','center':[29,58],'zoom':4}),
 ('Stalingrad changes the initiative','The surviving German forces at Stalingrad surrendered between 31 January and 2 February 1943. Soviet armies then gained the initiative. The point uses the wartime name for today’s Volgograd, on the Volga River.','Stalingrad',[44.52,48.71],19430202,U+'the-soviet-union-and-the-eastern-front',{'mode':'globe','center':[42,49],'zoom':4}),
 ('The advance reaches Berlin','Soviet forces drove the German military back and captured Berlin in spring 1945. This located endpoint does not suggest that one uninterrupted route linked every eastern campaign. The intervening fighting and civilian devastation extended across a much larger region.','Berlin',[13.4,52.52],1945,U+'the-soviet-union-and-the-eastern-front',None),
])
def pacific(st,d):
 st['sources'].append('us-army-atlas')
 sc=st['scenes'][3];sc['media']={'type':'image','src':'data/history/ww2/pacific-area-1942.jpg','alt':'US Army atlas map titled The Pacific Areas, 1 August 1942, showing Allied command boundaries across the ocean.','caption':'Command areas, 1 August 1942; not Japanese occupation. Original unwarped scan.','credit':'Courtesy of the University of Texas Libraries, The University of Texas at Austin; US Army Center of Military History.','licence':'Public domain','href':'data/history/ww2/pacific-area-1942.jpg'}
 sc['media']=[sc['media']];sc['sources'].append('us-army-atlas');sc['points']=[{'at':[153.03,-27.47],'label':'Brisbane','color':'c4','r':4},{'at':[-157.95,21.36],'label':'Pearl Harbor','color':'c1','r':4}]
 sc['layers']=[];sc['legend']=[{'color':'c1','label':'Hawaii reference anchor'},{'color':'c4','label':'Australia reference anchor'}]
 d['items']=[e for e in d['items'] if e['kind']!='3']
 st['notes']+=' Army atlas source/title/date and credit: '+ATLAS+'. Pacific boundaries divide Allied command areas, not Japanese occupation. Original scan used without a geographic warp; provisional wide-area polynomial fit was rejected as too inaccurate. Map anchors are rounded locations from the scan’s named geography.'
chapter('ww2-pacific','The Pacific','Island battles and command geography across a vast ocean.',[
 ('Pearl Harbor brings the United States into the war','Japan attacked Pearl Harbor on 7 December 1941. The harbour in Hawaii was a major US naval base; the attack brought the United States into World War II. Hawaii was then a US territory, not yet a state.','Pearl Harbor',[-157.95,21.36],19411207,'https://www.nps.gov/wwii/learn/historyculture/pearl-harbor.htm',{'mode':'globe','center':[-157,24],'zoom':3}),
 ('Midway: a battle around an atoll','The June 1942 battle near Midway checked Japanese expansion in the central Pacific. The Navy identifies the main carrier battle on 4 June; the point locates the atoll rather than reconstructing fleets’ positions.','Midway',[-177.37,28.21],19420604,N+'content/history/museums/nmusn/explore/photography/wwii/wwii-pacific/turning-the-japanese-tide/1942-june-battle-of-midway.html',{'mode':'globe','center':[-174,27],'zoom':3}),
 ('Guadalcanal opens a southern campaign','US Marines landed on Guadalcanal on 7 August 1942. The campaign combined land, sea and air fighting around the Solomon Islands. The point locates the island’s northern shore, not a landing beach perimeter.','Guadalcanal',[160.05,-9.42],19420807,N+'research/library/online-reading-room/title-list-alphabetically/b/battle-of-guadalcanal.html',{'mode':'globe','center':[158,-10],'zoom':4}),
 ('Command areas crossed the date line','The Army’s map of 1 August 1942 divides Allied commands across the Pacific. It shows why Hawaii and Australia mattered as distant organising centres. These printed boundaries classify commands, not land occupied by Japan; the original scan is shown below.','Pacific commands',[180,4],19420801,ATLAS,{'mode':'globe','center':[180,0],'zoom':1.3}),
 ('Okinawa: fighting close to Japan','US forces landed on Okinawa’s main island on 1 April 1945. The battle brought devastating combat to its civilian population as well as Japanese and Allied forces. No casualty estimate or occupation perimeter is inferred from this point.','Okinawa',[127.8,26.5],19450401,N+'content/history/museums/nmusn/explore/photography/wwii/wwii-pacific/okinawa.html',{'mode':'globe','center':[129,28],'zoom':4}),
],pacific)
def holocaust(st,d):
 st['notes']+=' Overall Holocaust context and six-million Jewish victim total: '+U+'introduction-to-the-holocaust. These are selected sites, not a complete site inventory or a casualty allocation. Static muted event points only; no animated pulses, decorative victim scaling, invented deportation routes or imported victim photographs.'
chapter('ww2-holocaust','The Holocaust','Ghettos, mass shootings, killing centres and liberation.',[
 ('Warsaw: forced confinement','German authorities established the Warsaw ghetto in 1940 and sealed it in November. They confined Jewish residents under conditions that caused severe suffering and death. This point locates Warsaw; it does not reconstruct the ghetto wall.','Warsaw',[21.01,52.23],1940,U+'warsaw',{'mode':'globe','center':[20,52],'zoom':5}),
 ('Babyn Yar: murder outside the camps','On 29–30 September 1941, German SS and police units and their auxiliaries murdered Jews at the Babyn Yar ravine near Kyiv. The site demonstrates that genocide included mass shootings outside camp systems. The point is an approximate site location, not a grave boundary.','Babyn Yar',[30.45,50.47],19410930,U+'kiev-and-babi-yar',{'mode':'globe','center':[29,51],'zoom':5}),
 ('Auschwitz-Birkenau: a killing centre','In 1942 the SS operated a killing centre at Auschwitz-Birkenau in German-occupied Poland. Jews deported from across Europe were murdered there; other targeted groups also suffered and died in the Auschwitz complex. This point locates Birkenau, without drawing unsupported deportation tracks.','Auschwitz-Birkenau',[19.18,50.03],1942,U+'auschwitz',{'mode':'globe','center':[19,50],'zoom':5}),
 ('Liberation did not erase the losses','British forces liberated Bergen-Belsen on 15 April 1945, finding survivors of catastrophic conditions. USHMM identifies six million Jewish victims of the Holocaust; Nazi Germany also persecuted and murdered millions of other victims. These selected locations cannot represent every person or place affected.','Bergen-Belsen',[9.91,52.76],19450415,'https://www.nationalarchives.gov.uk/explore-the-collection/stories/report-on-the-liberation-of-bergen-belsen/',{'mode':'globe','center':[11,52],'zoom':4.5}),
],holocaust)
chapter('ww2-bombing','Bombing cities','Selected attacks brought destruction to urban populations.',[
 ('London: the sustained Blitz begins','The sustained Blitz on London began on 7 September 1940. Bombing damaged homes and infrastructure and killed civilians. The point locates London, without implying that all attacks struck one site or covered the entire city uniformly.','London',[-0.13,51.51],19400907,'https://historicengland.org.uk/whats-new/features/blitz-stories/england-under-attack/',{'mode':'globe','center':[-1,52],'zoom':5}),
 ('Coventry: destruction and a surviving ruin','The Luftwaffe attacked Coventry on the night of 14 November 1940. The cathedral was destroyed; its ruins remain a witness to the raid. This point locates the city rather than an invented bomb-impact grid.','Coventry',[-1.51,52.41],19401114,'https://www.coventrycathedral.org.uk/locations/the-ruins',{'mode':'globe','center':[-1,52],'zoom':5}),
 ('Dresden: an Allied attack','British bombing on the night of 13–14 February 1945 devastated Dresden, followed by US attacks. Naming the attackers matters when mapping civilian destruction. This city point does not estimate a firestorm perimeter or select among disputed casualty totals.','Dresden',[13.74,51.05],19450213,'https://www.dhm.de/lemo/kapitel/zweiter-weltkrieg/kriegsverlauf/dresden',{'mode':'globe','center':[13,51],'zoom':5}),
 ('Hiroshima: an atomic bombing','The United States dropped an atomic bomb on Hiroshima on 6 August 1945. The National Archives documents destruction and large-scale loss of life. This point locates the city; it does not model a blast-radius circle or assign a precise death total.','Hiroshima',[132.46,34.4],19450806,A+'news/topics/hiroshima-nagasaki-75',{'mode':'globe','center':[133,34],'zoom':4.5}),
 ('Nagasaki: a second atomic bombing','The United States bombed Nagasaki on 9 August 1945. The two cities experienced different terrain and attack conditions. This chapter identifies the dates and cities without treating them as interchangeable casualty measurements.','Nagasaki',[129.87,32.75],19450809,A+'news/topics/hiroshima-nagasaki-75',{'mode':'globe','center':[131,33],'zoom':4.5}),
])
chapter('ww2-end','The end of the war','Surrender was announced, signed and implemented at different times.',[
 ('Reims: Germany signs surrender','Germany’s unconditional military surrender was signed at Reims on 7 May 1945. The document provided for fighting to stop the following day. The point locates the signing, not the position of every remaining German unit.','Reims',[4.03,49.26],19450507,A+'milestone-documents/surrender-of-germany',{'mode':'globe','center':[6,50],'zoom':4.5}),
 ('Berlin: a second signing','A further surrender document was signed in Berlin on 8 May 1945. The National Archives explains the importance of this act to the Soviet Union. Different ceremonies and time zones help explain different commemorative dates.','Berlin',[13.4,52.52],19450508,A+'milestone-documents/surrender-of-germany',None),
 ('An announcement reaches the public','US President Truman announced Japan’s acceptance of surrender on 14 August 1945 in Washington. The date was already 15 August in Japan. The point locates the announcement and distinguishes it from the later formal signing.','Washington',[-77.04,38.9],19450814,A+'news/vj-day-75',{'mode':'globe','center':[-78,39],'zoom':4}),
 ('Tokyo Bay: the formal Japanese surrender','Japanese representatives signed the surrender instrument aboard USS Missouri in Tokyo Bay on 2 September 1945. That formal act followed the August announcement. A single endpoint does not mean that displacement, hunger and postwar violence ended immediately.','Tokyo Bay',[139.75,35.45],19450902,A+'news/vj-day-75',{'mode':'globe','center':[140,35],'zoom':4}),
])
def borders(st,d):
 st['notes']+=' Date-scoped display aliases: Italy/Sardinia becomes Italy; Turkey (Ottoman Empire) becomes Turkey; Germany (Prussia) becomes Germany in 1938. Original labels are retained as sourceName in the derived files; geometry and dates are unchanged. Name evidence: https://history.state.gov/countries/italy/summary; https://history.state.gov/countries/germany; https://www.govinfo.gov/content/pkg/BILLS-115hres924ih/pdf/BILLS-115hres924ih.pdf.'
 st['data']['borders']='data/history/ww2/borders-names.json';st['sources'].append('cshapes')
 sc=st['scenes'][1];sc['switch']={'label':'Diplomatic snapshot','start':0,'options':[{'y':1938,'label':'1 Jan 1938'},{'y':1950,'label':'1 Jan 1950'}]};sc['layers']=[{'type':'borders','data':'borders','year':'{y}','labels':False}]
 sc['points']=[{'at':[21,52],'label':'Poland','color':'muted','r':3}]
 st['scenes'][2]['layers']=[{'type':'borders','data':'borders','year':1950,'labels':False}]
 st['scenes'][2]['points']=[{'at':[7.1,50.7],'label':'Federal Republic','color':'muted','r':3},{'at':[13.4,52.5],'label':'German Democratic Republic','color':'muted','r':3}]
 st['notes']+=' CShapes 2.0 diplomatic snapshots: 1 January 1938 and 1 January 1950, CC BY-NC-SA 4.0. They are not occupation zones, military control or a continuously updated front. German state formation: '+H+'countries/germany. Potsdam terms, including Polish administration pending final frontier settlement and population transfers: '+POTSDAM+'. These are administrative/diplomatic meanings; the 1950 map must not be called a 1945 snapshot. Wrocław/Breslau context: https://www.wroclaw.pl/dla-mieszkanca/koniec-festung-breslau-poczatek-polskiego-wroclawia.'
chapter('ww2-borders','The postwar borders','Administrative decisions, changed states and displaced people.',[
 ('Potsdam: administration before a final settlement','The 1945 Potsdam agreement placed former German territory east of the Oder–western Neisse line under Polish administration pending a final frontier determination. The Potsdam point locates the decision; it is not a traced border line.','Potsdam',[13.06,52.41],1945,POTSDAM,None),
 ('Poland’s mapped extent shifts west','Compare the CShapes diplomatic snapshots of 1 January 1938 and 1 January 1950. Poland’s mapped extent changes substantially. The dates are twelve years apart: these shapes do not reconstruct the intervening occupation or imply that every border question was settled in 1945.','Poland',[21,52],1950,'https://icr.ethz.ch/data/cshapes/',{'mode':'globe','center':[22,52],'zoom':4.5}),
 ('Two German states appear','The Federal Republic and German Democratic Republic were established in 1949. This CShapes snapshot is dated 1 January 1950, showing the two states in diplomatic geography. It is not a map of the four Allied military occupation zones.','German states',[11,52],1950,H+'countries/germany',{'mode':'globe','center':[12,51],'zoom':5}),
 ('Changing borders also moved people','Potsdam provided for transfers of German populations from Poland, Czechoslovakia and Hungary and called for orderly, humane treatment. Forced displacement accompanied the postwar transformation. Wrocław, formerly Breslau, locates one city affected by that change; no population count is inferred from the point.','Wrocław / Breslau',[17.04,51.11],1945,POTSDAM,{'mode':'globe','center':[17,51],'zoom':5}),
],borders)
print('Built eight WWII chapters')

